        int n = sc.nextInt();

        int one = 0;
        for (int i = 0; i < n; i++) {
            one++;
        }

        int two = 0;
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                two++;
            }
        }

        System.out.println("{word}");
